// One item, one string field "report", for the scan trigger.
//
// Same rule as the full test: this may only say PASSED when a delivery actually
// arrived with something in it. An empty body, or a body for an event nobody
// asked for, is a failure and says so.

// Run Once for All Items, so the delivery is read off the input rather than $json.
let body = {};
try {
  const first = $input.first();
  body = (first && first.json) || {};
} catch (e) {
  body = {};
}
const keys = Object.keys(body);
const event = body.event ?? body.type ?? null;
const wanted = 'scan.recorded';
const failures = [];
const lines = [];

const oneLine = (s, n) => String(s).replace(/\s+/g, ' ').trim().slice(0, n || 160);
const v = (x) => (x === undefined || x === null || x === '' ? 'MISSING' : String(x));

if (keys.length === 0) {
  failures.push('the delivery arrived with an empty body — nothing was sent, or it was not JSON');
} else if (!event) {
  failures.push('no "event" (or "type") field in the delivery, so there is no way to tell what happened');
} else if (event !== wanted) {
  failures.push('the delivery is for "' + oneLine(event, 60) + '", not "' + wanted + '"');
}

// The scan itself. These are the fields a scan delivery is supposed to carry;
// a missing one is reported by name rather than hidden behind a "?".
const scan = body.data ?? body.scan ?? {};
const codeId = scan.codeId ?? scan.code_id ?? scan.id ?? null;
const when = scan.scannedAt ?? scan.createdAt ?? body.createdAt ?? null;
if (keys.length && !codeId) {
  failures.push('the delivery names no QR code (no data.codeId), so it cannot be traced back to a code');
}

lines.push('event:            ' + v(event));
lines.push('QR code:          ' + v(codeId));
lines.push('when:             ' + v(when));
lines.push('top-level keys:   ' + (keys.length ? keys.join(', ') : 'NONE — the body was empty'));
lines.push('signature:        checked by the node before this workflow started; it answers 401 and does not start the workflow when the check fails');

let payload = '';
try {
  payload = JSON.stringify(body).slice(0, 1200);
} catch (e) {
  payload = '(could not be printed: ' + oneLine(e.message, 80) + ')';
  failures.push('the delivery could not be serialised: ' + oneLine(e.message, 80));
}

const report = [
  failures.length
    ? 'RESULT: FAILED — ' + failures.length + ' problem' + (failures.length === 1 ? '' : 's') + ' with this delivery'
    : 'RESULT: PASSED — a signed ' + wanted + ' delivery arrived with a scan in it',
  'QRSalt trigger — delivery received ' + new Date().toISOString(),
  ''.padEnd(72, '-'),
  ...lines,
  ''.padEnd(72, '-'),
  'FAILURES: ' + (failures.length ? failures.length : 'none'),
  ...failures.map((f) => '  - ' + f),
  'PAYLOAD:',
  '  ' + payload,
].join('\n');

return [{ json: { report, passed: failures.length === 0 } }];
